sealed partial class SoundCanvas {
 public bool MathPlane;
 void PaintMathPlane(Graphics g,RectangleF v){if(!MathPlane)return;using(var brush=new SolidBrush(Color.White))using(var font=new Font("Segoe UI",9)){for(int i=-5;i<=5;i++){g.DrawString(i.ToString(),font,brush,v.X+(300+i*40)*v.Width/600,v.Y+240*v.Height/450);if(i!=0)g.DrawString(i.ToString(),font,brush,v.X+308*v.Width/600,v.Y+(225-i*40)*v.Height/450);}g.DrawString("X →",font,brush,v.Right-50,v.Y+220*v.Height/450);g.DrawString("Y ↑",font,brush,v.X+300*v.Width/600,v.Y);}}
}

