  MathNumber(p,"Coordenada equis",mathX,-5,5,0,.1m,()=>{});mathX.DecimalPlaces=1;MathNumber(p,"Coordenada ye",mathY,-5,5,0,.1m,()=>{});mathY.DecimalPlaces=1;
