 void InitMath(){MathPrepare();MathPlane();}
 bool MathCurrent(){if(mathData==null||mathInput.Text!=MathValue("expression")){Say("Hay cambios pendientes. Pulsa Preparar expresión antes de leer o guardar.");return false;}return true;}void MathReadValue(string key){if(MathCurrent())MathSpeak(MathValue(key));}void MathPrepare(){Stop();mathRequestedInput=mathInput.Text;Send("MATH|"+B64(mathInput.Text)+"|"+(++mathRequest));}
 void MathPlane(){Stop();mathTrace=0;mathFeature="";Send("MATH_PLANE|"+mathPlane.SelectedIndex);}
 string MathValue(string key){return mathData!=null&&mathData.ContainsKey(key)?Convert.ToString(mathData[key],CultureInfo.InvariantCulture):"Prepara primero un ejercicio.";}
 List<string> MathItems(string key){var result=new List<string>();if(mathData!=null&&mathData.ContainsKey(key))foreach(object item in (System.Collections.IEnumerable)mathData[key])result.Add(Convert.ToString(item,CultureInfo.InvariantCulture));return result;}
 void MathRefresh(){mathChoices.Items.Clear();string key=new string[]{"tokens","digits","rows","columns","steps","development"}[Math.Max(0,mathMode.SelectedIndex)];foreach(string s in MathItems(key))mathChoices.Items.Add((mathChoices.Items.Count+1)+". "+s);if(mathChoices.Items.Count>0)mathChoices.SelectedIndex=0;}
 void MathMove(int delta){if(!MathCurrent())return;if(mathChoices.Items.Count==0)return;int next=mathChoices.SelectedIndex+delta;if(mathListening.SelectedIndex==2){if(mathEditingKey.Length>0)MathSaveNote();while(next>=0&&next<mathChoices.Items.Count&&!MathNotes().ContainsKey("fragment:"+mathMode.SelectedIndex+":"+next))next+=delta;if(next<0||next>=mathChoices.Items.Count){MathSpeak("No hay más anotaciones en esta dirección y este orden de lectura.");return;}}mathChoices.SelectedIndex=Math.Max(0,Math.Min(mathChoices.Items.Count-1,next));if(mathListening.SelectedIndex==0){Stop();mathReadout.Text="Fragmento "+(mathChoices.SelectedIndex+1)+" seleccionado. Pulsa Leer o repetir cuando quieras.";}else MathRead();}
 void MathRead(){if(!MathCurrent())return;if(mathChoices.SelectedItem!=null){if(mathEditingKey.Length>0)MathSaveNote();string key="fragment:"+mathMode.SelectedIndex+":"+mathChoices.SelectedIndex;string content=mathListening.SelectedIndex==2?MathNote(key,0)+". "+MathNote(key,1):Convert.ToString(mathChoices.SelectedItem)+(mathListening.SelectedIndex==1&&MathNotes().ContainsKey(key)?". Nota: "+MathNote(key,0):"");MathSpeak("Fragmento "+(mathChoices.SelectedIndex+1)+" de "+mathChoices.Items.Count+". "+content);}}
 void StopMathVoice(){if(mathSpeech!=null)try{mathSpeech.SpeakAsyncCancelAll();}catch{}}
 void MathSpeak(string text){Stop();mathReadout.Text=text;Say(text);if(mathNarration.Checked&&mathSpeech!=null)try{mathSpeech.SpeakAsync(text);}catch{Say("No se pudo iniciar la voz; la explicación queda disponible en el cuadro de texto.");}}
 void MathAt(bool sound,bool speak){Stop();double sx=300+(double)mathX.Value*40,sy=225-(double)mathY.Value*40;mathMoving=true;mathCanvas.MoveLogical(sx,sy);mathMoving=false;Send("MATH_AT|"+mathPlane.SelectedIndex+"|"+Dec(mathX.Value)+"|"+Dec(mathY.Value)+"|"+sound.ToString().ToLowerInvariant()+"|"+speak.ToString().ToLowerInvariant()+"|manual");}
 void MathShift(int dx,int dy){mathX.Value=Math.Max(-5,Math.Min(5,mathX.Value+dx));mathY.Value=Math.Max(-5,Math.Min(5,mathY.Value+dy));MathAt(false,true);}
 void ReceiveMath(string[] a){if(a[0]=="MATHDATA"){if(a.Length>2&&a[2]!=mathRequest.ToString(CultureInfo.InvariantCulture))return;mathData=json.Deserialize<Dictionary<string,object>>(Decode(a[1]));if(mathInput.Text==mathRequestedInput)mathInput.Text=MathValue("expression");if(!mathHistory.Items.Contains(MathValue("expression"))){mathHistory.Items.Insert(0,MathValue("expression"));while(mathHistory.Items.Count>20)mathHistory.Items.RemoveAt(20);}mathHistory.SelectedIndex=mathHistory.Items.IndexOf(MathValue("expression"));mathGrid.Text=MathValue("grid").Replace("\n",Environment.NewLine);MathSetBook(null);MathRefresh();Say("Ejercicio matemático preparado.");}else if(a[0]=="MATHPLANE"){if(a.Length>3&&a[3]!=mathPlane.SelectedIndex.ToString(CultureInfo.InvariantCulture))return;mathOverview=Decode(a[1]);mathCanvas.Shapes=ParseShapes(a[2]);mathCanvas.Invalidate();}else if(a[0]=="MATHRESTORE"){var restored=json.Deserialize<Dictionary<string,object>>(Decode(a[1]));mathPlane.SelectedIndex=Convert.ToInt32(restored["plane"]);MathPlane();mathX.Value=Convert.ToDecimal(restored["x"],CultureInfo.InvariantCulture);mathY.Value=Convert.ToDecimal(restored["y"],CultureInfo.InvariantCulture);MathAt(false,false);MathSpeak(Convert.ToString(restored["description"]));}else if(a[0]=="MATHPOINT"){var point=json.Deserialize<Dictionary<string,object>>(Decode(a[1]));if(Convert.ToInt32(point["plane"])!=mathPlane.SelectedIndex)return;mathTrace=Math.Max(0,Convert.ToInt32(point["index"]));mathX.Value=Convert.ToDecimal(point["x"],CultureInfo.InvariantCulture);mathY.Value=Convert.ToDecimal(point["y"],CultureInfo.InvariantCulture);MathAt(false,false);MathSpeak(Convert.ToString(point["description"]));}else{string text=Decode(a[1]),feature=text.Substring(text.IndexOf('.')+1);if(a.Length<3||a[2]=="manual"||feature!=mathFeature){mathFeature=feature;MathSpeak(text);}}}
 void MathSave(string key,string name){if(!MathCurrent())return;using(var dialog=new SaveFileDialog()){dialog.FileName=name;dialog.Filter="Archivo de ejercicio|*.*";if(dialog.ShowDialog(this)==DialogResult.OK)try{File.WriteAllText(dialog.FileName,MathValue(key),new UTF8Encoding(false));Say("Archivo matemático guardado.");}catch(Exception e){Say(e.Message);}}}
 void MathSavePlane(){using(var dialog=new SaveFileDialog()){dialog.FileName="plano-matematico.json";dialog.Filter="Plano matemático JSON|*.json";if(dialog.ShowDialog(this)==DialogResult.OK)try{File.WriteAllText(dialog.FileName,json.Serialize(new Dictionary<string,object>{{"schema","formas-math-plane-v1"},{"plane",mathPlane.SelectedIndex},{"x",mathX.Value},{"y",mathY.Value}}),new UTF8Encoding(false));Say("Plano y punto guardados.");}catch(Exception e){Say(e.Message);}}}void MathOpen(){using(var dialog=new OpenFileDialog()){dialog.Filter="Ejercicios matemáticos JSON|*.json";if(dialog.ShowDialog(this)==DialogResult.OK)try{if(new FileInfo(dialog.FileName).Length>16000)throw new InvalidDataException("El ejercicio supera 16 KB.");Stop();mathRequestedInput=mathInput.Text;Send("MATH_LOAD|"+B64(File.ReadAllText(dialog.FileName,Encoding.UTF8))+"|"+(++mathRequest));}catch(Exception e){Say(e.Message);}}}
}
